import json

def prune_old_tool_outputs(messages: list, keep_recent_turns: int = 4) -> list:
    """<i class="qref" title="Tested in the practice exam under this concept">Agent context mgmt</i>: Summarize/prune older tool outputs while preserving active task state."""
    if len(messages) <= keep_recent_turns:
        return messages
    pruned = []
    for idx, msg in enumerate(messages[:-keep_recent_turns]):
        if msg.get("role") == "user" and isinstance(msg.get("content"), list):
            # Compress older tool_result payloads into a concise summary
            pruned.append({
                "role": "user",
                "content": [{"type": "text", "text": "[Summarized prior tool output: step completed]"}]
            })
        else:
            pruned.append(msg)
    return pruned + messages[-keep_recent_turns:]

def validate_tool_args(tool_name: str, tool_input: dict, allowed_schemas: dict) -> bool:
    """<i class="qref" title="Tested in the practice exam under this concept">Tool arg validation</i>: Validate tool_use arguments against schema before dispatching."""
    schema_keys = allowed_schemas.get(tool_name, set())
    return set(tool_input.keys()).issubset(schema_keys)

def save_checkpoint(task_id: str, step_index: int, messages: list, active_state: dict):
    """<i class="qref" title="Tested in the practice exam under this concept">Fault tolerance</i>: Persist intermediate state so interrupted 30-60 min tasks can resume."""
    payload = {"task_id": task_id, "step": step_index, "state": active_state, "messages": messages}
    with open(f"/tmp/checkpoint_{task_id}.json", "w") as f:
        json.dump(payload, f)

